-- TEST-only shared recurring Slack foundation; no activation, access grants or source imports.
begin;
set local lock_timeout='3s';set local statement_timeout='30s';set local search_path=public,pg_catalog;
lock table of_test_deploy.migrations in share row exclusive mode;
do $$begin
 if current_setting('serviceos.release_target',true) is distinct from 'saatxzwxvdvqevbnskxy' or coalesce(current_setting('serviceos.release_source_sha256',true),'') !~ '^[a-f0-9]{64}$' then raise exception 'Explicit TEST target and checksum required';end if;
 if md5((jsonb_build_object('health',jsonb_build_object(
 'runtime',jsonb_build_object(
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text) order by p.oid::regprocedure::text),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('email_ingestion_account_guard_v2','email_ingestion_checkpoint_json_v2','email_ingestion_count_v2','email_ingestion_evidence_v2','email_ingestion_keys_v2','email_ingestion_payload_v2','email_ingestion_recovery_v2','email_ingestion_run_guard_v2','email_ingestion_transition_result_v2','email_ingestion_transition_v2','learn_operator_input_access','learn_operator_input_immutable','learn_slack_claim_jobs','platform_jobs_claim','platform_jobs_complete_email_v1','phone_retry_state','phone_pending_readiness','phone_select_pending','learn_capture_allowed','learn_capture_control_state','learn_operator_capture_controls','learn_operator_capture_control_request','learn_capture_admission','learn_capture_job_allowed','learn_capture_defer_job','learn_email_transition_immutable','learn_email_transition_prepare','learn_email_transition_pending','learn_email_transition_apply','learn_email_job_attempt','learn_email_attempt_lease','learn_email_store_guard','learn_email_store_existing','learn_email_store_page','learn_email_job_fail','learn_email_enqueue')),
 'tables',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,
 'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid)) order by conname),'[]') from pg_constraint where conrelid=c.oid),
 'indexes',(select coalesce(jsonb_agg(indexdef order by indexname),'[]') from pg_indexes where schemaname='public' and tablename=c.relname),
 'policies',(select coalesce(jsonb_agg(to_jsonb(x) order by x.policyname),'[]') from pg_policies x where x.schemaname='public' and x.tablename=c.relname),
 'triggers',(select coalesce(jsonb_agg(pg_get_triggerdef(oid) order by tgname),'[]') from pg_trigger where tgrelid=c.oid and not tgisinternal)) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('tenants','profiles','feature_flags','platform_jobs','slack_workspace_pacing','email_accounts','email_sync_runs','email_threads','email_messages','email_ingestion_checkpoints','email_ingestion_transitions','email_oauth_tokens','google_workspace_connections','google_workspace_mailboxes','phone_recordings','phone_transcripts','phone_ai_insights','phone_sync_runs','learn_capture_control_requests','learn_email_transition_requests','learn_email_transition_settlements','learn_email_job_attempts') and c.relkind='r'),
 'views',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'definition',pg_get_viewdef(c.oid),'options',c.reloptions,'acl',c.relacl::text) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='phone_recording_pipeline_state'),
 'ledger',(select jsonb_agg(jsonb_build_object('migration_name',migration_name,'source_sha256',source_sha256,'project_ref',project_ref) order by migration_name) from of_test_deploy.migrations)
),
 'tables',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,
 'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'acl',a.attacl::text) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid)) order by conname),'[]') from pg_constraint where conrelid=c.oid),
 'policies',(select coalesce(jsonb_agg(to_jsonb(p) order by p.policyname),'[]') from pg_policies p where p.schemaname='public' and p.tablename=c.relname),
 'triggers',(select coalesce(jsonb_agg(pg_get_triggerdef(oid) order by tgname),'[]') from pg_trigger where tgrelid=c.oid and not tgisinternal)) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('client_portal_access','client_programmes','client_programme_revisions','client_programme_notes','receptionist_workspaces','receptionist_access','receptionist_feedback','client_notification_outbox') and c.relkind='r'),
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text) order by p.oid::regprocedure::text),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('current_user_is_openfolk_operator','client_programme_stamp','client_programme_record_revision','receptionist_feedback_stamp','queue_client_feedback','claim_client_notifications','client_portal_write_context')),
 'defaultPrivileges',(select coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'type',d.defaclobjtype,'acl',d.defaclacl::text) order by d.defaclrole::regrole::text,n.nspname,d.defaclobjtype),'[]') from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where d.defaclnamespace=0 or n.nspname='public')
),'slack',jsonb_build_object(
 
 'tables',(select coalesce(jsonb_agg(jsonb_build_object('name',c.relname,'rls',c.relrowsecurity,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,
 'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'acl',a.attacl::text) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
 'constraints',(select coalesce(jsonb_agg(jsonb_build_object('name',conname,'definition',pg_get_constraintdef(oid)) order by conname),'[]') from pg_constraint where conrelid=c.oid),
 'policies',(select coalesce(jsonb_agg(to_jsonb(p) order by p.policyname),'[]') from pg_policies p where p.schemaname='public' and p.tablename=c.relname),
 'triggers',(select coalesce(jsonb_agg(pg_get_triggerdef(oid) order by tgname),'[]') from pg_trigger where tgrelid=c.oid and not tgisinternal)) order by c.relname),'[]') from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('connector_accounts','tenant_connectors','provider_connections','slack_history_imports','slack_messages','slack_message_versions','platform_authority_grants','view_as_context','slack_recurring_channels','slack_recurring_requests') and c.relkind='r'),
 'functions',(select coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text) order by p.oid::regprocedure::text),'[]') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('current_tenant_id','current_user_role','slack_version_immutable','learn_slack_recurring_access','learn_slack_recurring_control','learn_slack_recurring_read','learn_slack_schedule_recurring')),
 'defaultPrivileges',(select coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(d.defaclrole),'schema',n.nspname,'type',d.defaclobjtype,'acl',d.defaclacl::text) order by d.defaclrole::regrole::text,n.nspname,d.defaclobjtype),'[]') from pg_default_acl d left join pg_namespace n on n.oid=d.defaclnamespace where d.defaclnamespace=0 or n.nspname='public')
),
 'indexes',(select coalesce(jsonb_agg(indexdef order by tablename,indexname),'[]') from pg_indexes where schemaname='public' and tablename in ('connector_accounts','tenant_connectors','provider_connections','slack_history_imports','slack_messages','slack_message_versions','platform_authority_grants','view_as_context','slack_recurring_channels','slack_recurring_requests'))))::text) <> '5b8642b5dae2e70d07b5a7e40391e639' then raise exception 'Exact recurring Slack prerequisites required';end if;
end $$;
create temporary table serviceos_slack_recurring_preserved on commit drop as select 'public.email_messages' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.email_messages s union all select 'public.phone_calls' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.phone_calls s union all select 'public.phone_recordings' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.phone_recordings s union all select 'public.phone_transcripts' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.phone_transcripts s union all select 'public.slack_messages' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.slack_messages s union all select 'public.slack_message_versions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.slack_message_versions s union all select 'public.interactions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.interactions s union all select 'public.people' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.people s union all select 'public.companies' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.companies s union all select 'public.customer_cards' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.customer_cards s union all select 'public.sites' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.sites s union all select 'public.jobs' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.jobs s union all select 'public.provider_connections' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.provider_connections s union all select 'public.tenant_connectors' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.tenant_connectors s union all select 'public.connector_accounts' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.connector_accounts s union all select 'public.platform_jobs' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.platform_jobs s union all select 'public.feature_flags' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.feature_flags s union all select 'public.learn_business_input_pages' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_business_input_pages s union all select 'public.learn_business_input_versions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_business_input_versions s union all select 'public.learn_business_input_observations' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_business_input_observations s union all select 'public.provider_connection_events' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.provider_connection_events s union all select 'public.platform_authority_grants' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.platform_authority_grants s union all select 'public.learn_operator_input_requests' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_operator_input_requests s union all select 'public.profiles' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.profiles s union all select 'public.authority_permissions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.authority_permissions s union all select 'public.learn_business_input_request_gates' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_business_input_request_gates s union all select 'public.learn_business_input_request_permits' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_business_input_request_permits s union all select 'vault.secrets' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from vault.secrets s union all select 'public.tenants' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.tenants s union all select 'public.view_as_context' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.view_as_context s union all select 'public.config_versions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.config_versions s union all select 'public.learn_commusoft_connection_requests' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_commusoft_connection_requests s union all select 'public.learn_commusoft_verification_requests' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_commusoft_verification_requests s union all select 'public.learn_commusoft_verification_permits' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_commusoft_verification_permits s union all select 'public.learn_commusoft_verification_results' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_commusoft_verification_results s union all select 'public.learn_business_input_links' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_business_input_links s union all select 'public.learn_business_input_projection_attempts' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_business_input_projection_attempts s union all select 'public.learn_business_input_projection_batches' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_business_input_projection_batches s union all select 'public.contact_points' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.contact_points s union all select 'public.graph_nodes' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.graph_nodes s union all select 'public.graph_edges' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.graph_edges s union all select 'public.graph_events' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.graph_events s union all select 'public.email_accounts' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.email_accounts s union all select 'public.email_sync_runs' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.email_sync_runs s union all select 'public.email_threads' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.email_threads s union all select 'public.email_ingestion_checkpoints' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.email_ingestion_checkpoints s union all select 'public.email_ingestion_transitions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.email_ingestion_transitions s union all select 'public.google_workspace_connections' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.google_workspace_connections s union all select 'public.google_workspace_mailboxes' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.google_workspace_mailboxes s union all select 'public.phone_sync_runs' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.phone_sync_runs s union all select 'public.phone_ai_insights' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.phone_ai_insights s union all select 'public.slack_workspace_pacing' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.slack_workspace_pacing s union all select 'public.learn_capture_control_requests' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_capture_control_requests s union all select 'public.learn_email_transition_requests' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_email_transition_requests s union all select 'public.learn_email_transition_settlements' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_email_transition_settlements s union all select 'public.learn_email_job_attempts' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.learn_email_job_attempts s union all select 'public.client_portal_access' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.client_portal_access s union all select 'public.client_programmes' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.client_programmes s union all select 'public.client_programme_revisions' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.client_programme_revisions s union all select 'public.client_programme_notes' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.client_programme_notes s union all select 'public.receptionist_workspaces' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.receptionist_workspaces s union all select 'public.receptionist_access' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.receptionist_access s union all select 'public.receptionist_feedback' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.receptionist_feedback s union all select 'public.client_notification_outbox' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.client_notification_outbox s union all select 'public.slack_history_imports' as name,count(*)::int as count,md5(coalesce(string_agg(md5(row_to_json(s)::text),'' order by md5(row_to_json(s)::text)),'')) as fingerprint from public.slack_history_imports s;
-- Explicit ongoing channel approval; no activation, credentials or schedule seeded.
-- Each new window uses the existing fenced Slack worker and retained page protocol.
create function public.learn_slack_recurring_access(p_tenant uuid,p_write boolean) returns boolean
language sql stable security definer set search_path=pg_catalog as $$
 select coalesce(auth.uid() is not null and p_tenant is not null and p_write is not null
  and (case when p_write then
   ((p_tenant=public.current_tenant_id() and public.current_user_role() in ('owner','admin'))
     or public.current_user_is_openfolk_operator('platform.controlplane.admin'))
   and not exists(select 1 from public.view_as_context where actor_user_id=auth.uid() and ended_at is null
    and (expires_at is null or expires_at>now()))
  else p_tenant=public.current_tenant_id() or public.current_user_is_openfolk_operator('platform.controlplane.view') end),false);
$$;
revoke all on function public.learn_slack_recurring_access(uuid,boolean) from public,anon;
grant execute on function public.learn_slack_recurring_access(uuid,boolean) to authenticated;
create table public.slack_recurring_channels (
 account_id uuid primary key references public.connector_accounts(id),
 tenant_id uuid not null references public.tenants(id),
 connection_id uuid not null references public.provider_connections(id),
 connection_revision timestamptz not null,
 team_id text not null check(team_id ~ '^T[A-Z0-9]+$'),
 channel_id text not null check(channel_id ~ '^C[A-Z0-9]+$'),
 approved_by uuid not null references public.profiles(id),
 enabled boolean not null,
 revision bigint not null default 1 check(revision>0),
 next_start timestamptz not null,
 current_import uuid references public.slack_history_imports(id),
 last_state text not null default 'ready',
 next_check_at timestamptz not null default clock_timestamp(),
 updated_at timestamptz not null default clock_timestamp(),
 check(isfinite(next_start) and next_start>=to_timestamp(0))
);
alter table public.slack_recurring_channels enable row level security;
create index slack_recurring_due on public.slack_recurring_channels(next_check_at,account_id) where enabled;
revoke all on public.slack_recurring_channels from public,anon,authenticated,service_role;
grant select on public.slack_recurring_channels to authenticated,service_role;
create policy slack_recurring_read on public.slack_recurring_channels for select to authenticated
 using(public.learn_slack_recurring_access(tenant_id,false));
create table public.slack_recurring_requests (
 id uuid primary key,tenant_id uuid not null references public.tenants(id),
 actor_id uuid not null references public.profiles(id),definition jsonb not null,receipt jsonb not null,
 created_at timestamptz not null default clock_timestamp()
);
alter table public.slack_recurring_requests enable row level security;
revoke all on public.slack_recurring_requests from public,anon,authenticated,service_role;
create trigger slack_recurring_request_immutable before update or delete on public.slack_recurring_requests
 for each row execute function public.slack_version_immutable();

create function public.learn_slack_recurring_control(p_tenant uuid,p_request uuid,p_account uuid,
 p_revision bigint,p_enabled boolean,p_reason text,p_mode text default 'apply',p_actor uuid default auth.uid()) returns jsonb
language plpgsql security definer set search_path=pg_catalog as $$
declare a public.connector_accounts%rowtype;c public.provider_connections%rowtype;
 s public.slack_recurring_channels%rowtype;r public.slack_recurring_requests%rowtype;
 definition jsonb;answer jsonb;cfg jsonb;boundary timestamptz;resume_paused boolean;
begin
 if current_setting('transaction_isolation')<>'read committed' then
  raise exception 'slack_recurring_snapshot' using errcode='22023';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('learn-work-registry',0));
 perform pg_advisory_xact_lock(hashtextextended('learn-roster:'||p_tenant::text,0));
 if p_actor is distinct from auth.uid() or not public.learn_slack_recurring_access(p_tenant,true) then
  raise exception 'slack_recurring_forbidden' using errcode='42501';end if;
 if p_request is null or p_account is null or p_revision is null or p_revision<0 or p_enabled is null
  or length(btrim(coalesce(p_reason,''))) not between 1 and 1000 or p_mode is null or p_mode not in ('apply','check','cancel') then
  raise exception 'slack_recurring_invalid' using errcode='22023';end if;
 definition:=jsonb_build_object('accountId',p_account,'revision',p_revision,'enabled',p_enabled,'reason',btrim(p_reason));
 perform pg_advisory_xact_lock(hashtextextended('learn-slack-recurring-request:'||p_request::text,0));
 select * into r from public.slack_recurring_requests where id=p_request;
 if found then
  if r.tenant_id<>p_tenant or r.actor_id<>auth.uid() or r.definition<>definition then
   raise exception 'slack_recurring_request_changed' using errcode='40001';end if;
  return r.receipt;
 end if;
 answer:=jsonb_build_object('tenantId',p_tenant,'requestId',p_request,'accountId',p_account,
  'state',case when p_mode='cancel' then 'cancelled' else 'pending' end);
 if p_mode='check' then return answer;end if;
 if p_mode='cancel' then
  insert into public.slack_recurring_requests(id,tenant_id,actor_id,definition,receipt) values(p_request,p_tenant,auth.uid(),definition,answer);
  return answer;
 end if;
 -- Same setup lock as manual channel imports; subscription precedes account locks.
 perform pg_advisory_xact_lock(hashtextextended('learn-slack-setup:'||p_tenant::text,0));
 select * into s from public.slack_recurring_channels where account_id=p_account for update;
 if (found and (s.tenant_id<>p_tenant or s.revision<>p_revision)) or (not found and p_revision<>0) then
  raise exception 'slack_recurring_changed' using errcode='40001';end if;
 select * into a from public.connector_accounts where id=p_account and tenant_id=p_tenant for update;
 if not found then raise exception 'slack_recurring_account_unavailable' using errcode='42501';end if;
 cfg:=a.settings->'slack_history';
 resume_paused:=s.account_id is not null and not s.enabled and s.current_import is not null
  and cfg->>'consentReference'='learn-slack-import:'||s.current_import::text
  and cfg->'approved'='false'::jsonb;
 resume_paused:=coalesce(resume_paused,false);
 if p_enabled then
  if a.status is distinct from 'active' or coalesce(cfg->>'channelId','') !~ '^C[A-Z0-9]+$'
   or coalesce(cfg->>'teamId','') !~ '^T[A-Z0-9]+$'
   or coalesce(cfg->>'latest','') !~ '^\d{1,12}\.\d{1,6}$'
   or not exists(select 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=p_tenant
    and connector_id='slack' and enabled and status='active') then
   raise exception 'slack_recurring_finish_initial_import' using errcode='55000';end if;
  if not resume_paused and a.sync_cursor->'complete' is distinct from 'true'::jsonb then
   raise exception 'slack_recurring_finish_initial_import' using errcode='55000';end if;
  if not resume_paused and exists(select 1 from public.platform_jobs where tenant_id=p_tenant and job_type='slack.history_sync'
   and payload->>'connector_account_id'=p_account::text and status in ('queued','running','retrying')) then
   raise exception 'slack_recurring_window_active' using errcode='55000';end if;
  -- A true checkpoint alone is insufficient: require matching durable publication.
  if not resume_paused and not exists(select 1 from public.platform_jobs where tenant_id=p_tenant and job_type='slack.history_sync'
   and payload->>'connector_account_id'=p_account::text and status='succeeded'
   and metadata->'slack_page_v1'->'next'=a.sync_cursor
   and metadata->'slack_page_v1'->>'account_id'=p_account::text) then
   raise exception 'slack_recurring_completion_unverified' using errcode='55000';end if;
  select * into c from public.provider_connections where id=(cfg->>'connectionId')::uuid and tenant_id=p_tenant for share;
  if not found or c.provider is distinct from 'slack' or c.status is distinct from 'configured' or c.revoked_at is not null
   or c.non_secret_config->>'team_id' is distinct from cfg->>'teamId'
   or ('bot_token'=any(c.configured_fields)) is distinct from true or c.secret_refs->>'bot_token' is null then
   raise exception 'slack_recurring_connection_unavailable' using errcode='55000';end if;
  boundary:=to_timestamp((cfg->>'latest')::double precision);
  if boundary>clock_timestamp() then raise exception 'slack_recurring_future_window' using errcode='22023';end if;
  if resume_paused then
   if c.id<>s.connection_id or c.updated_at<>s.connection_revision or cfg->>'teamId'<>s.team_id or cfg->>'channelId'<>s.channel_id then
    raise exception 'slack_recurring_connection_changed' using errcode='40001';end if;
   -- Restore only the approved unfinished scope. Expiry and page limits stay as
   -- recorded; exhausted work still uses the explicit existing recovery flow.
   update public.slack_recurring_channels set enabled=true,revision=revision+1,approved_by=auth.uid(),
    last_state='ready',next_check_at=clock_timestamp(),updated_at=clock_timestamp()
    where account_id=p_account returning * into s;
  else
  insert into public.slack_recurring_channels(account_id,tenant_id,connection_id,connection_revision,team_id,channel_id,approved_by,enabled,next_start)
   values(p_account,p_tenant,c.id,c.updated_at,cfg->>'teamId',cfg->>'channelId',auth.uid(),true,boundary)
   on conflict(account_id) do update set connection_id=excluded.connection_id,connection_revision=excluded.connection_revision,
    team_id=excluded.team_id,channel_id=excluded.channel_id,
    approved_by=excluded.approved_by,enabled=true,next_start=excluded.next_start,current_import=null,
    revision=slack_recurring_channels.revision+1,last_state='ready',next_check_at=clock_timestamp(),updated_at=clock_timestamp()
   returning * into s;
  end if;
  update public.connector_accounts set settings=jsonb_set(settings,'{slack_history,approved}','true') where id=p_account;
 else
  if s.account_id is null then raise exception 'slack_recurring_not_configured' using errcode='55000';end if;
  update public.slack_recurring_channels set enabled=false,revision=revision+1,last_state='disabled',updated_at=clock_timestamp()
   where account_id=p_account returning * into s;
  -- Stop further requests for this recurring window without erasing its checkpoint.
  if s.current_import is not null and cfg->>'consentReference'='learn-slack-import:'||s.current_import::text then
   update public.connector_accounts set settings=jsonb_set(settings,'{slack_history,approved}','false') where id=p_account;
  end if;
 end if;
 answer:=jsonb_build_object('tenantId',p_tenant,'requestId',p_request,'accountId',p_account,'state','recorded','enabled',s.enabled,'revision',s.revision);
 insert into public.slack_recurring_requests(id,tenant_id,actor_id,definition,receipt) values(p_request,p_tenant,auth.uid(),definition,answer);
 return answer;
end $$;

create function public.learn_slack_schedule_recurring(p_batch integer default 10) returns jsonb
language plpgsql security definer set search_path=pg_catalog as $$
declare s public.slack_recurring_channels%rowtype;a public.connector_accounts%rowtype;
 c public.provider_connections%rowtype;cfg jsonb;previous jsonb;approval jsonb;
 boundary timestamptz;ending timestamptz;request_id uuid;job_id uuid;state text;
 checked integer:=0;queued integer:=0;held integer:=0;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'slack_recurring_forbidden' using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed' or p_batch is null or p_batch not between 1 and 50 then
  raise exception 'slack_recurring_invalid' using errcode='22023';end if;
 -- Select due IDs before taking the established tenant setup lock. All callers
 -- then take the subscription and account locks in that same order.
 for s in select * from public.slack_recurring_channels where enabled and next_check_at<=clock_timestamp()
  order by next_check_at,account_id limit p_batch
 loop
  if not pg_try_advisory_xact_lock(hashtextextended('learn-slack-setup:'||s.tenant_id::text,0)) then continue;end if;
  select * into s from public.slack_recurring_channels where account_id=s.account_id and enabled
   and next_check_at<=clock_timestamp() for update;
  if not found then continue;end if;
  checked:=checked+1;state:='ready';boundary:=s.next_start;
  if not public.learn_capture_allowed(s.tenant_id,'slack') then state:='capture_paused';
  end if;
  perform 1 from public.profiles p where p.id=s.approved_by and
   ((p.tenant_id=s.tenant_id and p.role in ('owner','admin')) or exists(select 1 from public.platform_authority_grants g
     where g.profile_id=p.id and g.permission='platform.controlplane.admin'
     and coalesce(g.effective_from,'-infinity')<=now() and coalesce(g.effective_to,'infinity')>now())) for share;
  if state='ready' and not found then state:='approval_changed';end if;
  select * into a from public.connector_accounts where id=s.account_id and tenant_id=s.tenant_id for update;
  if not found or a.status is distinct from 'active' then state:='account_unavailable';end if;
  cfg:=a.settings->'slack_history';
  if state='ready' and cfg->'approved' is distinct from 'true'::jsonb then state:='approval_changed';end if;
  select * into c from public.provider_connections where id=s.connection_id and tenant_id=s.tenant_id for share;
  if not found or c.provider is distinct from 'slack' or c.status is distinct from 'configured' or c.revoked_at is not null
   or c.updated_at is distinct from s.connection_revision or c.non_secret_config->>'team_id' is distinct from cfg->>'teamId'
   or cfg->>'connectionId' is distinct from s.connection_id::text or ('bot_token'=any(c.configured_fields)) is distinct from true
   or cfg->>'teamId' is distinct from s.team_id or cfg->>'channelId' is distinct from s.channel_id
   or c.secret_refs->>'bot_token' is null then state:='connection_changed';end if;
  if not exists(select 1 from public.tenant_connectors where id=a.tenant_connector_id and tenant_id=s.tenant_id
   and connector_id='slack' and enabled and status='active') then state:='connector_paused';end if;
  if state='ready' and exists(select 1 from public.platform_jobs where tenant_id=s.tenant_id and job_type='slack.history_sync'
   and payload->>'connector_account_id'=s.account_id::text and status in ('queued','running','retrying')) then state:='window_active';end if;
  if state='ready' then
   if s.current_import is not null and cfg->>'consentReference' is distinct from 'learn-slack-import:'||s.current_import::text then state:='window_changed';
   elsif a.sync_cursor->'complete' is distinct from 'true'::jsonb then state:='window_incomplete';
   elsif not exists(select 1 from public.platform_jobs where tenant_id=s.tenant_id and job_type='slack.history_sync'
    and payload->>'connector_account_id'=s.account_id::text and status='succeeded'
    and metadata->'slack_page_v1'->'next'=a.sync_cursor and metadata->'slack_page_v1'->>'account_id'=s.account_id::text)
    then state:='completion_unverified';
   elsif coalesce(cfg->>'latest','') !~ '^\d{1,12}\.\d{1,6}$' then state:='window_changed';
   else
    boundary:=to_timestamp((cfg->>'latest')::double precision);
    if (s.current_import is null and boundary is distinct from s.next_start) or boundary<s.next_start then state:='window_changed';end if;
   end if;
  end if;
  if state='ready' then
   -- Fifteen-minute windows bound busy-channel pages; 2-minute settling delay.
   ending:=least(boundary+interval '15 minutes',clock_timestamp()-interval '2 minutes');
   if ending-boundary<interval '1 minute' then state:='caught_up';
   else
    request_id:=gen_random_uuid();job_id:=gen_random_uuid();
    previous:=jsonb_build_object('settings',cfg,'checkpoint',a.sync_cursor);
    approval:=jsonb_build_object('approved',true,'connectionId',c.id,'teamId',cfg->>'teamId','channelId',cfg->>'channelId',
     'oldest',to_char(extract(epoch from boundary),'FM999999999999.000000'),
     'latest',to_char(extract(epoch from ending),'FM999999999999.000000'),
     'consentReference','learn-slack-import:'||request_id::text,'expiresAt',clock_timestamp()+interval '24 hours','maxPages',10);
    update public.connector_accounts set settings=settings||jsonb_build_object('slack_history',approval),sync_cursor='{}' where id=a.id;
    insert into public.platform_jobs(id,tenant_id,connector_id,job_type,job_key,status,max_attempts,available_at,payload,created_by)
     values(job_id,s.tenant_id,'slack','slack.history_sync','slack.history:'||a.id::text,'queued',5,clock_timestamp(),jsonb_build_object('connector_account_id',a.id),s.approved_by);
    insert into public.slack_history_imports(id,tenant_id,account_id,job_id,approved_by,definition,previous_state)
     values(request_id,s.tenant_id,a.id,job_id,s.approved_by,jsonb_build_object('connectionId',c.id,'connectionRevision',c.updated_at,
      'channelId',cfg->>'channelId','start',boundary,'end',ending,'maxPages',10,'recurringAccountId',a.id,
      'recurringRevision',s.revision,'reason','Approved recurring channel capture'),previous);
    update public.slack_recurring_channels set current_import=request_id,next_start=boundary where account_id=a.id;
    queued:=queued+1;state:='window_queued';
   end if;
  end if;
  if state not in ('window_queued','window_active','caught_up') then held:=held+1;end if;
  update public.slack_recurring_channels set last_state=state,next_check_at=clock_timestamp()+interval '60 seconds',updated_at=clock_timestamp() where account_id=s.account_id;
 end loop;
 return jsonb_build_object('checked',checked,'queued',queued,'held',held);
end $$;
